(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(my*0.03-t*0.4)*8+Math.cos(mx*0.025+t*0.3)*6;
  const w2y = Math.cos(mx*0.028+t*0.35)*8+Math.sin(my*0.022-t*0.45)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.2],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+1)*40,0.14,1.3,0.7],
    [400+Math.cos(t*0.55+2)*70,220+Math.sin(t*0.75+4)*50,0.05,2.8,1.15]
  ];
  let aS=0,iS=0,wS=0;
  for(const[sX,sY,f,sp,wt]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*wt;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*wt;
    wS+=Math.sin(d*f*0.5-t*sp*0.4+3.0)*wt*0.5;
  }
  const n=8,act=aS/n,inh=iS/n,wav=wS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+sy*0.06-t*1.8)*0.15+Math.cos(sx*0.05-sy*0.07+t*1.3)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.3+Math.sin(dist*0.08-ang*2+t*0.8)*0.15+Math.cos(dist*0.03+ang*5-t*2.0)*0.15;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const reaction=Math.tanh((act-inh*0.6+wav*0.3+bg*0.25+spiral)*2.2);
  const rd2=Math.tanh((act*0.5+wav-inh*0.4+cell)*1.8);
  const micro=Math.sin(sx*0.4+sy*0.3+t*4)*Math.sin(sx*0.35-sy*0.45-t*3.5)*0.08;
  const blend=reaction*0.5+cell*0.15+rd2*0.3+micro;
  const v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,40,85],[15,75,105],[25,120,120],[60,160,100],[140,185,80],[210,190,60],[220,140,55],[190,80,60],[140,40,65],[80,20,55],[30,12,48],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:(Math.abs(rd2)>0.6?1.1:1.0);
  const shimmer=1.0+Math.sin(ang*2+dist*0.1-t*3)*0.05;
  const vig=1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/420*0.25;
  const fl=lum*edge*shimmer*Math.max(0.4,vig);
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*fl)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*fl)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*fl)|0
  ];
}
